47. @Log4j2
48. @RequiredArgsConstructor
49. public class DocsAuthorizationManager implements AuthorizationManager<RequestAuthorizationContext> {
50. 
51.     private static final String GET_PROJECTS_DOCS_BY_PATH_URI = "/api/projects-docs/get-by-path"; // NOSONAR
52. 
53.     private final SecurityService securityService;
54. 
55.     private static String getRequestParameterPath(@NotNull HttpServletRequest request) {
56.         String[] parameterValues = request.getParameterValues("path");
57.         if (parameterValues.length == 1) {
58.             return parameterValues[0];
59.         }
60.         return "";
61.     }
62. 
63.     private static String getProjectName(HttpServletRequest request) {
64.         String[] parts = request.getRequestURI().split("/", 4);
65.         if (request.getContextPath().isEmpty()) {
66.             return parts.length > 1 ? parts[1] : "";
67.         }
68.         return parts.length > 2 ? parts[2] : "";
69.     }
70. 
71.     @Override
72.     public AuthorizationDecision check(Supplier<Authentication> authenticationSupplier, RequestAuthorizationContext context) {
73.         HttpServletRequest request = context.getRequest();
74.         log.info("Request uri: {}", request.getRequestURI());
75.         log.info("Request url: {}", request.getRequestURL());
76.         log.info("Server context-path: {}", request.getContextPath());
77. 
78.         Authentication authentication = authenticationSupplier.get();
79.         if (authentication instanceof DbtDocsAuthenticationToken) {
80.             User user = (User) authentication.getPrincipal();
81.             if (user == null) {
82.                 return new AuthorizationDecision(false);
83.             }
84.             String preferredUsername = user.getUserName();
85.             String email = user.getEmail();
86.             log.info("Received Principal with username {} and email {}. Requesting Uri: {}", preferredUsername, email,
87.                     request.getRequestURI());
88.             if (requestedEndpoint(request, GET_PROJECTS_DOCS_BY_PATH_URI)) {
89.                 String requestParameterPath = getRequestParameterPath(request);
90.                 String requestedProject = getRequestedProject(requestParameterPath);
91.                 log.debug("Requested project: {}", requestedProject);
92.                 return authorizeRequestedProject(user, requestedProject);
93.             } else if (!requestedEndpoint(request, "/api")) {
94.                 String projectName = getProjectName(request);
95.                 log.info("Received project name url request {}", projectName);
96.                 if (!securityService.canAccessProject(user.getRoles(), projectName)) {
97.                     return new AuthorizationDecision(false);
98.                 }
99.             }
100. 
101.             return new AuthorizationDecision(true);
102.         }
103.         return new AuthorizationDecision(false);
104.     }
105. 
106.     public boolean isUserAuthorizedOnProject(User user, String projectName) {
107.         if (user.getRoles().stream().anyMatch(r -> r.getKey().equals(Role.ADMIN_ROLE_KEY))) {
108.             return true;
109.         }
110.         return user.getRoles()
111.                 .stream()
112.                 .filter(Role::isEnabled)
113.                 .anyMatch(r -> r.getKey().equalsIgnoreCase(projectName) && r.getPrivileges().stream().anyMatch(p -> p.getName().equals(Privilege.READ_PRIVILEGE)));
114.     }
115. 
116.     private boolean requestedEndpoint(@NotNull HttpServletRequest request, String endpointPath) {
117.         Path endpointPathWithContextPath = Paths.get(request.getContextPath(), endpointPath);
118.         Path requestedUriPath = Paths.get(request.getRequestURI().toLowerCase());
119.         log.info("endpointPathWithContextPath: {}", endpointPathWithContextPath);
120.         log.info("requestedUriPath: {}", requestedUriPath);
121.         log.info("Startswith? {}", requestedUriPath.startsWith(endpointPathWithContextPath));
122.         return requestedUriPath.startsWith(endpointPathWithContextPath);
123.     }
124. 
125.     @NotNull
126.     private AuthorizationDecision authorizeRequestedProject(User user, String projectName) {
127.         if (ObjectUtils.isEmpty(projectName)) {
128.             return new AuthorizationDecision(false);
129.         }
130.         boolean isAuthorized = isUserAuthorizedOnProject(user, projectName);

